        try {
            const messages = await getChatMessages(getCurrentMessageId());
            const characterData = _.get(messages, '[0].data.stat_data');

            if (!characterData) { return; }

            $('[data-path]').each(function() {
                const path = $(this).data('path');
                let value = _.get(characterData, `${path}[0]`, 'N/A');
                if (path === '关系.是否为恋人') {
                    value = value === true ? '是❤️' : '还不是...';
                }
                $(this).text(value);
            });

            $('.variable-row').each(function() {
                const valueEl = $(this).find('[data-path-value]');
                const sensoryEl = $(this).find('[data-path-sensory]');
                const barEl = $(this).find('[data-path-bar]');

                if (valueEl.length) {
                    const path = valueEl.data('path-value');
                    valueEl.text(_.get(characterData, `${path}[0]`, 0));
                }
                if (sensoryEl.length) {
                    const path = sensoryEl.data('path-sensory');
                    sensoryEl.text(_.get(characterData, `${path}[0]`, ''));
                }
                if (barEl.length) {
                    const path = barEl.data('path-bar');
                    const value = _.get(characterData, `${path}[0]`, 0);
                    const min = barEl.data('min') || 0;
                    const max = barEl.data('max') || 100;
                    const percentage = Math.max(0, Math.min(100, ((value - min) / (max - min)) * 100));
                    barEl.css('width', `${percentage}%`);
                }
            });

        } catch (error) {
            console.error("手记更新时出错:", error);
        }
    }

    $(document).ready(function() {
        $('.section-header').trigger('click');
        updateDisplay();
        $(document).on('message-rendered', function() {
            updateDisplay();
        });
    });
</script>

