            const characterData = _.get(messages, '[0].data.stat_data');

            if (!characterData) { return; }

            $('[data-path]').each(function() {
                const path = $(this).data('path');
                let value = _.get(characterData, `${path}[0]`, 'N/A');
                if (path === '关系.是否为恋人') {
                    value = value === true ? '是❤️' : '还不是...';
                }
                $(this).text(value);
            });

            $('.variable-row').each(function() {
                const valueEl = $(this).find('[data-path-value]');
                const sensoryEl = $(this).find('[data-path-sensory]');
                const barEl = $(this).find('[data-path-bar]');

                if (valueEl.length) {
                    const path = valueEl.data('path-value');
                    valueEl.text(_.get(characterData, `${path}[0]`, 0));
                }
                if (sensoryEl.length) {
                    const path = sensoryEl.data('path-sensory');
                    sensoryEl.text(_.get(characterData, `${path}[0]`, ''));
                }
